"use client"

import { createContext, useContext, useState, useEffect, ReactNode, useCallback, useMemo } from "react"
import { createClient } from "@/lib/supabase"

interface UserProfile {
  id: string
  username: string
  email: string
  full_name: string | null
  phone: string | null
  role: string
  permissions: any | null
  is_active: boolean
  last_login: string | null
}

interface AuthContextType {
  user: any | null
  profile: UserProfile | null
  loading: boolean
  signOut: () => Promise<void>
  hasPermission: (module: string, action: 'view' | 'insert' | 'edit' | 'delete' | 'print') => boolean
  passwordResetRequired: boolean
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

const supabase = createClient()

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<any | null>(null)
  const [profile, setProfile] = useState<UserProfile | null>(null)
  const [loading, setLoading] = useState(true)
  const [resolvedPermissions, setResolvedPermissions] = useState<any>(null)

  const passwordResetRequired = useMemo(() => {
    return !!(user && profile && profile.last_login === null)
  }, [user, profile])

  useEffect(() => {
    let mounted = true

    const timeoutId = setTimeout(() => {
      if (mounted && loading) {
        setLoading(false)
      }
    }, 5000)

    const getProfile = async (userId: string) => {
      try {
        const { data, error } = await supabase
          .from('profiles')
          .select(`
            *,
            role_data:role_permissions (
              permissions
            )
          `)
          .eq('auth_id', userId)
          .single()

        if (error) {
          console.error("Auth: Profile fetch error", error)
          return null
        }

        const rawProfile = data as any

        // Resolve Permissions: 
        // 1. Check profile.permissions (specific to user)
        // 2. Fallback to role_data.permissions (inherited from role)
        const permissions = rawProfile.permissions || rawProfile.role_data?.permissions || {}

        console.log("Auth: Raw Profile Data:", rawProfile)
        console.log("Auth: Resolved Permissions (Profile or Role):", permissions)

        if (mounted) {
          setResolvedPermissions(permissions)
        }

        return rawProfile as UserProfile
      } catch (e) {
        console.error("Auth: Unexpected error in getProfile", e)
        return null
      }
    }

    const syncProfile = async (session: any) => {
      if (!mounted) return
      if (session?.user) {
        setUser(session.user)
        const p = await getProfile(session.user.id)
        if (mounted) setProfile(p)
      } else {
        setUser(null)
        setProfile(null)
        setResolvedPermissions(null)
      }
      if (mounted) setLoading(false)
    }

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return

      if (event === 'INITIAL_SESSION' || event === 'SIGNED_IN' || event === 'USER_UPDATED') {
        await syncProfile(session)
      } else if (event === 'SIGNED_OUT') {
        setUser(null)
        setProfile(null)
        setResolvedPermissions(null)
        setLoading(false)
      }
    })

    return () => {
      mounted = false
      clearTimeout(timeoutId)
      subscription.unsubscribe()
    }
  }, [])

  const signOut = useCallback(async () => {
    await supabase.auth.signOut()
    window.location.href = "/"
  }, [])

  const hasPermission = useCallback((module: string, action: 'view' | 'insert' | 'edit' | 'delete' | 'print'): boolean => {
    if (!resolvedPermissions) {
      console.warn(`Auth: No permissions resolved yet for module ${module}`)
      return false
    }

    // Check module exists
    const modulePerms = resolvedPermissions[module]
    if (!modulePerms) {
      console.warn(`Auth: Module "${module}" not found in permissions`)
      return false
    }

    // Check action
    const allowed = modulePerms[action] === true
    console.log(`Auth: Permission Check - Module: ${module}, Action: ${action}, Allowed: ${allowed}`)
    return allowed
  }, [resolvedPermissions])

  const value = useMemo(() => ({
    user,
    profile,
    loading,
    signOut,
    hasPermission,
    passwordResetRequired
  }), [user, profile, loading, signOut, hasPermission, passwordResetRequired])

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider")
  }
  return context
}